import type { ArcRotateCamera } from "@babylonjs/lite";

export function focusOn(camera: ArcRotateCamera, point: { x: number; y: number; z: number }): void {
    // alpha, beta and radius are left unchanged, so the orientation and distance stay the same.
    // The camera position is derived from target, radius and angles, so moving the target to
    // `point` moves the camera by the same offset and the camera looks straight at `point`.
    // A new object is assigned instead of mutating the old target, so any reference-based cache sees the change.
    camera.target = { x: point.x, y: point.y, z: point.z };
}
```

The function sets the camera's target to a copy of `point` and leaves the angles and radius alone, so the camera orbits the picked part from then on. I'm not sure the library refreshes the camera's view and world matrices right away after a plain target assignment, which your label code depends on. The declarations don't expose a way to force that refresh, and I couldn't check the library. Also, I assumed `Vec3` is a plain `{x, y, z}` shape, and I didn't call the internal `_clampToLimits` hook.
